@using sv_440439bf77d54d4889d18ed1ab6bda7a.Services
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@rendermode InteractiveServer

<div class="d-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold">Warehouse:</label>
    <select class="form-select form-select-sm" style="width:auto"
            value="@_selectedId" @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseInfo.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    private string _selectedId = "WH-001";

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-001";
        var match = WarehouseInfo.AvailableWarehouses
            .FirstOrDefault(w => w.Id == _selectedId);

        var info = new WarehouseInfo
        {
            WarehouseId = match.Id ?? _selectedId,
            WarehouseName = match.Name ?? _selectedId
        };

        // Pushes the new value to every [CascadingParameter] subscriber.
        await WarehouseSource.NotifyChangedAsync(info);
    }
}

@using sv_440439bf77d54d4889d18ed1ab6bda7a.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

@if (AlertService.CurrentLowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@AlertService.CurrentLowStockCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-auto">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Background-thread-safe: InvokeAsync marshals to the sync context.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

