@page "/dashboard"
@using sv_440439bf77d54d4889d18ed1ab6bda7a.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4" style="max-width: 28rem;">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text">
            <strong>@Warehouse?.WarehouseName</strong>
            <span class="text-muted">(@Warehouse?.WarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4" style="max-width: 28rem;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        @if (_isPolling)
        {
            <p class="card-text fs-3">
                @if (AlertService.CurrentLowStockCount > 0)
                {
                    <span class="badge bg-danger">@AlertService.CurrentLowStockCount items below minimum</span>
                }
                else
                {
                    <span class="badge bg-success">All stock levels OK</span>
                }
            </p>
            <p class="text-muted"><small>Refreshes every 10 seconds</small></p>
        }
        else
        {
            <p class="text-muted">Starting alert monitor…</p>
        }
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Subscribe so that when polling updates the service,
        // this component re-renders too.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _isPolling = true;

            // Fetch immediately on load, then every 10 s.
            await PollOnceAsync();
            StateHasChanged();

            // Fire-and-forget the loop — it is cancelled in Dispose.
            _ = PollLoopAsync(_cts.Token);
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await PollOnceAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollOnceAsync()
    {
        if (Warehouse is null) return;
        var count = await AlertService.GetLowStockCountAsync(Warehouse.WarehouseId);
        // UpdateCount fires OnChange → every subscriber (including sidebar badge) re-renders.
        AlertService.UpdateCount(count);
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

